fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    let n = list.len();
    // `k` is 1-based, convert to zero-based index of element to remove
    let remove_idx = k - 1;

    // Pre-allocate vector with capacity n - 1
    let mut new_list = Vec::with_capacity(n - 1);

    // Copy prefix: elements before remove_idx
    new_list.extend_from_slice(&list[0..remove_idx]);
    // Copy suffix: elements after remove_idx
    new_list.extend_from_slice(&list[remove_idx + 1..n]);

    new_list
}